"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["98000"],{44127(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.rotulo_obrigatorio","status":422,"titulo":"O r\xf3tulo do item \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.item_formulario.rotulo_obrigatorio","requisitos":[],"oQueAconteceu":["O `rotulo` de um item do formul\xe1rio, ou de um campo de grupo, est\xe1 vazio ou s\xf3 com espa\xe7os. O r\xf3tulo \xe9 o texto com que o campo aparece para o candidato. A mensagem \xe9 \\"O r\xf3tulo do item \xe9 obrigat\xf3rio.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].rotulo` ou, no campo de um grupo, `grupos[g].subitens[j].rotulo`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Cada item recusado tem a pr\xf3pria entrada, junto das demais recusas da forma do item, e o item de forma recusada n\xe3o segue para a confer\xeancia contra o cat\xe1logo de fatos. Nada \xe9 gravado.","No formul\xe1rio de inscri\xe7\xe3o, o item dos dados b\xe1sicos do candidato vale pelo r\xf3tulo do conjunto b\xe1sico, e o r\xf3tulo enviado para ele n\xe3o \xe9 conferido aqui.","A recusa vale para o texto presente. A propriedade `rotulo` ausente ou nula \xe9 recusada antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Informe em `rotulo` o texto que o candidato deve ler no campo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);